/**
 * Fallback chapters (roadmap H.14). For each interest × band × style a small
 * pool of chapters pre-generated by library mode (same gates, higher bar).
 * When a live chapter fails after its rewrite, times out or the provider is
 * down, a fallback is served with a template bridge sentence. The student
 * never sees an error. Fallback rate is tracked (target < 2%).
 */

export type FallbackCandidate = { id: string; interest: string; gradeBand: string; styleKey: string; title: string; body: string; choices: Array<{ label: string; intent: string }>; usedCount: number };

/** Prefers same style, then same interest, then least used; never the same fallback twice in a saga. */
export function pickFallback(pool: FallbackCandidate[], wanted: { interest: string; gradeBand: string; styleKey: string }, alreadyUsed: string[]): FallbackCandidate | null {
  const fresh = pool.filter((f) => f.gradeBand === wanted.gradeBand && !alreadyUsed.includes(f.id));
  const score = (f: FallbackCandidate) => (f.styleKey === wanted.styleKey ? 0 : 2) + (f.interest === wanted.interest ? 0 : 1) + f.usedCount / 1000;
  return [...fresh].sort((a, b) => score(a) - score(b))[0] ?? null;
}

const BRIDGES = [
  (choice: string) => `Tu avais choisi : ${choice}. Ce que tu ne savais pas encore, c'est que le chemin allait faire un détour.`,
  (choice: string) => `${choice} — c'était ta décision. Mais l'histoire, parfois, prend un raccourci inattendu.`,
  (choice: string) => `Tu venais de choisir : ${choice}. Quelques heures plus tard, tout avait changé de décor.`,
];

/** Template bridge (no model): links the student's last choice to the fallback chapter. */
export function bridgeSentence(choiceLabel: string | null, seed: number): string {
  if (!choiceLabel) return "L'histoire reprend un peu plus loin.";
  const label = choiceLabel.replace(/[.!?…]+$/u, "").trim();
  return BRIDGES[Math.abs(seed) % BRIDGES.length](label.charAt(0).toLocaleLowerCase("fr") + label.slice(1));
}

export function fallbackRate(chapters: Array<{ source: "live" | "fallback" }>): number {
  if (chapters.length === 0) return 0;
  return chapters.filter((c) => c.source === "fallback").length / chapters.length;
}
